// WantsBlink reports whether an Images row is in an animated state (running,
// or an action observed on it). A queued row and a remembered failure are
// steady. It is the level the router's BlinkingView check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	return false
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

// scanningImage reports whether an image is queued or being scanned, whoever
// started it.
func (m Model) scanningImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}
// proxy is one host repeated, and a group's members all answer to the same host
// too (§3.18). Joined with a slash because that is exactly the head of the pull
// reference: `docker pull nexus.example.com/dhi-io-proxy/eclipse-temurin:21`.
// Plain text only — Rule 122.
func registryRef(url, repoPrefix string) string {
	if repoPrefix == "" {
		return url
	}
	return strings.TrimSuffix(url, "/") + "/" + repoPrefix
}

// membersCell reports what the last discovery for a group found, and when.
//
// The "when" is not decoration: a cache with no visible age is worse than the
// re-detection it replaced, because it looks current whatever it holds
// (§3.8, decision 3). Plain text only — Rule 122.
func (m *Model) membersCell(reg config.RegistryItem) string {
	if reg.Kind != config.KindGroup {
		return ""
	}
	if m.refreshingGroups[reg.Slug] {
		// The spinner's frame, not its View(): the latter renders through a
		// style, and a table cell carries no escape sequence.
		return spinner.Dot.Frames[m.spinnerFrameIdx%len(spinner.Dot.Frames)] + " refreshing"
	}
	entry, ok := m.groupCache[reg.Slug]
	if !ok {
		return "never" // declared a group, never asked
	}
	return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
}

// loggedCell reports the login status for a registry URL, and says it
// differently when the secret is inline in the engine's auth file (§3.68).
//
// Not a column of its own: under Docker Desktop a "store" column would read
// `desktop` on every row. The warning only appears where there is something
// to see.
func (m *Model) loggedCell(mode, url string) string {
	if !config.UsesCredentials(mode) {
		return "-"
	}
	switch m.registryLoginStatus[url] {
	case docker.LoginHelper:
		return theme.IconOK
	case docker.LoginInline:
		return theme.IconWarning
	default:
		return theme.IconError
	}
}

// drilledGroup returns the group the tab has entered, or nil at the top level.
func (m *Model) drilledGroup() *config.RegistryItem {
	if m.registryGroupSlug == "" {
		return nil
	}
	for i := range m.registries {
		if m.registries[i].Slug == m.registryGroupSlug {
			return &m.registries[i]
		}
	}
	return nil
}

func (m *Model) updateRegistryTable() {
	if group := m.drilledGroup(); group != nil {
		m.updateGroupMemberTable(*group)
		return
	}
	rows := make([]registryRow, 0, len(m.registries))
	for i, reg := range m.registries {
		rows = append(rows, registryRow{
			alias:   reg.Alias,
			url:     registryRef(reg.URL, reg.RepoPrefix),
			kind:    reg.Kind,
			auth:    reg.AuthMode,
			logged:  m.loggedCell(reg.AuthMode, reg.URL),
			members: m.membersCell(reg),
			config:  i,
		})
	}
	m.setRegistryRows(rows)
}

// updateGroupMemberTable fills the table with one group's discovered members.
//
// A member is not a config entry: it has no alias of its own to edit, its
// credentials are the group's, and it is what the cache holds — so the columns
// say `inherit`, carry no member count, and the row points at no config entry.
func (m *Model) updateGroupMemberTable(group config.RegistryItem) {
	entry := m.groupCache[group.Slug]
	rows := make([]registryRow, 0, len(entry.Members))
	for _, member := range entry.Members {
		rows = append(rows, registryRow{
			alias:  member.Alias,
			url:    registryRef(member.URL, member.RepoPrefix),
			kind:   "member",
			auth:   config.AuthInherit,
			logged: m.loggedCell(group.AuthMode, group.URL),
			config: -1,
		})
	}
	m.setRegistryRows(rows)
}

func (m *Model) setRegistryRows(rows []registryRow) {
	m.registryTable.SetItems(rows)
	m.registryTable.Resize(m.width, m.tableHeight())
}
	if cmd := m.refreshSelectedGroupCmd(); cmd != nil {
		cmds = append(cmds, cmd, m.spinner.Tick)
	}
	m.updateRegistryTable()
	return m, tea.Batch(cmds...)
}

